  background:repeating-linear-gradient(90deg,var(--ink) 0 2px,transparent 2px 4px,var(--ink) 4px 5px,transparent 5px 10px,var(--ink) 10px 13px,transparent 13px 15px,var(--ink) 15px 16px,transparent 16px 21px)}
.barcode span{display:block; margin-top:7px; font:500 9px 'IBM Plex Mono'; letter-spacing:.34em; color:var(--muted)}
/* stamps */
.stamp{display:inline-block; font:600 12px/1 'IBM Plex Mono'; letter-spacing:.3em; text-transform:uppercase; color:var(--red);
  border:2.5px solid var(--red); outline:1px solid var(--red); outline-offset:3px; padding:9px 15px 8px; mix-blend-mode:multiply; opacity:.92; white-space:nowrap}
.stamp-green{color:var(--pine); border-color:var(--pine); outline-color:var(--pine)}
.stamp-wrap{position:absolute; right:-16px; top:-22px}
.js .inv-stamp{opacity:0}
.invoice.in .inv-stamp{animation:thump .55s cubic-bezier(.2,1.4,.4,1) .7s forwards}
@keyframes thump{0%{opacity:0; transform:rotate(16deg) scale(2.2)}70%{opacity:.92; transform:rotate(8deg) scale(.94)}100%{opacity:.92; transform:rotate(8deg) scale(1)}}
/* ---------- ticker ---------- */
.ticker{border-top:1px solid var(--ink); border-bottom:1px solid var(--ink); background:var(--ink); color:var(--paper); overflow:hidden; padding:10px 0}
.ticker-track{display:flex; width:max-content; animation:tick 38s linear infinite}
.t-half{display:flex; align-items:center; white-space:nowrap}
.t-item{font:500 11px 'IBM Plex Mono'; letter-spacing:.22em; text-transform:uppercase; padding:0 26px}
.t-sep{color:var(--gold); font-size:10px}
@keyframes tick{to{transform:translateX(-50%)}}
/* ---------- layout ---------- */
.layout{max-width:1240px; margin:0 auto; padding:56px 28px 30px; display:grid; grid-template-columns:290px minmax(0,1fr); gap:56px; align-items:start}
.rail{position:sticky; top:20px; border:1px solid var(--ink); background:var(--paper-2); display:flex; flex-direction:column; max-height:calc(100vh - 40px)}
.rail-head{padding:13px 16px; border-bottom:1px solid var(--ink); font-size:10px; letter-spacing:.22em; text-transform:uppercase; display:flex; justify-content:space-between; color:var(--ink-soft)}
.rail-head b{color:var(--red); font-weight:600}
.toc{overflow-y:auto; scrollbar-width:thin; scrollbar-color:var(--line) transparent}
.toc a{display:grid; grid-template-columns:34px 1fr; gap:10px; padding:9px 16px; text-decoration:none; color:var(--ink-soft);
  border-bottom:1px solid rgba(203,189,159,.5); font:500 .95rem 'Newsreader'; transition:background .25s,color .25s,transform .25s}
.toc a:hover{background:rgba(29,92,71,.09); color:var(--ink); transform:translateX(3px)}
.t-num{font:500 10px 'IBM Plex Mono'; letter-spacing:.1em; color:var(--muted); padding-top:2px}
.toc a.active{background:var(--ink); color:var(--paper)}
.toc a.active .t-num{color:var(--gold)}
.rail-progress{border-top:1px solid var(--ink); padding:14px 16px 16px}
.rp-top{display:flex; justify-content:space-between; font:500 9.5px 'IBM Plex Mono'; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); margin-bottom:9px}
#rpLabel{color:var(--pine)}
.rp-bar{height:7px; border:1px solid var(--ink); position:relative}
#rpFill{position:absolute; inset:0; width:4%; background:var(--pine); transition:width .35s ease}
/* ---------- entries ---------- */
.js .reveal{opacity:0; transform:translateY(26px); transition:opacity .8s ease, transform .8s cubic-bezier(.22,1,.36,1)}
.js .reveal.in{opacity:1; transform:none}
.entry{position:relative; border:1px solid var(--ink); background:var(--paper-2); padding:30px 34px 28px;
  box-shadow:5px 5px 0 rgba(34,29,21,.1); scroll-margin-top:24px; transition:transform .35s ease, box-shadow .35s ease}
.entry:hover{transform:translate(-2px,-2px); box-shadow:9px 9px 0 rgba(34,29,21,.14)}
.e-head{display:flex; gap:22px; align-items:flex-start; border-bottom:1px solid var(--line); padding-bottom:18px; margin-bottom:24px}
.e-num{font:900 56px/.9 'Fraunces'; letter-spacing:-.02em; transition:color .35s}
.entry:hover .e-num{color:var(--red)}
.e-of{font:500 11px 'IBM Plex Mono'; color:var(--muted); letter-spacing:.14em; margin-top:8px; display:block}
.e-tag{font:500 9.5px 'IBM Plex Mono'; letter-spacing:.2em; text-transform:uppercase; color:var(--pine); margin-bottom:8px}
.e-name{font:900 clamp(1.65rem,3vw,2.35rem)/1.06 'Fraunces'; letter-spacing:-.01em;
  background:linear-gradient(var(--red),var(--red)) no-repeat 0 100%/0 2px; transition:background-size .5s ease}
.entry:hover .e-name{background-size:100% 2px}
.e-body{display:grid; grid-template-columns:minmax(0,1fr) 190px; gap:32px}
.verse{font:500 clamp(1.2rem,1.9vw,1.55rem)/1.62 'Newsreader'; padding-top:4px}
.js .verse .lm-i{transform:translateY(115%); transition:transform .8s cubic-bezier(.22,1,.36,1)}
.entry.in .verse .lm-i{transform:none}
.entry .verse .lm:nth-child(1) .lm-i{transition-delay:.05s}
.entry .verse .lm:nth-child(2) .lm-i{transition-delay:.13s}
.entry .verse .lm:nth-child(3) .lm-i{transition-delay:.21s}
.entry .verse .lm:nth-child(4) .lm-i{transition-delay:.29s}
.entry .verse .lm:nth-child(5) .lm-i{transition-delay:.37s}
.verse p:last-child .lm-i{font-style:italic; background:linear-gradient(transparent 64%, rgba(178,58,32,.18) 64%)}
.e-side{display:flex; flex-direction:column; gap:14px}
.photo{border:1px solid var(--ink); overflow:hidden; aspect-ratio:4/5; position:relative; background:#d8ccb2; flex:0 0 auto}
.photo img{width:100%; height:100%; object-fit:cover; filter:sepia(.55) contrast(1.02) brightness(.97) saturate(.85);
  animation:breathe 16s ease-in-out infinite alternate; transition:filter .5s}
.entry:hover .photo img{filter:sepia(.12) contrast(1.02) brightness(1)}
@keyframes breathe{from{transform:scale(1.05)}to{transform:scale(1.15) translate(-2%,-2%)}}
.photo figcaption{position:absolute; left:0; right:0; bottom:0; background:rgba(34,29,21,.85); color:var(--paper);
  font:500 8.5px 'IBM Plex Mono'; letter-spacing:.2em; text-transform:uppercase; padding:5px 8px}
.note{font:italic 400 .95rem/1.55 'Newsreader'; color:var(--ink-soft); padding-left:12px; border-left:2px solid var(--red)}
.n-label{font:600 9px 'IBM Plex Mono'; font-style:normal; letter-spacing:.24em; text-transform:uppercase; color:var(--red); display:block; margin-bottom:5px}
.e-stamp{position:absolute; top:20px; right:24px; font-size:10px; padding:6px 11px 5px}
.js .e-stamp{opacity:0}
.entry.in .e-stamp{animation:thump2 .5s cubic-bezier(.2,1.4,.4,1) .6s forwards}
@keyframes thump2{0%{opacity:0; transform:rotate(-18deg) scale(2.1)}70%{opacity:.9; transform:rotate(-7deg) scale(.94)}100%{opacity:.9; transform:rotate(-7deg) scale(1)}}
.perf{height:44px; position:relative}
.perf::before{content:""; position:absolute; top:50%; left:0; right:0; border-top:2px dashed rgba(34,29,21,.32)}
.perf::after{content:""; position:absolute; top:50%; left:50%; width:9px; height:9px; background:var(--paper); border:1px solid rgba(34,29,21,.45);
  transform:translate(-50%,-50%) rotate(45deg)}
/* ---------- memo interlude ---------- */
.memo{display:grid; grid-template-columns:1fr 1fr; border:1px solid var(--ink); background:var(--paper-2); margin:64px 0; box-shadow:5px 5px 0 rgba(34,29,21,.1)}
.memo-letter{padding:32px 34px; border-right:1px dashed var(--line); font:400 1.04rem/1.75 'Newsreader'; color:var(--ink-soft)}
.memo-head{font:600 11px 'IBM Plex Mono'; letter-spacing:.26em; text-transform:uppercase; color:var(--red); margin-bottom:18px; display:inline-block; padding-bottom:10px; border-bottom:2px solid var(--ink)}
.memo-table{padding:32px 34px}
.memo-table table{width:100%; border-collapse:collapse}
.memo-table th{font:600 9.5px 'IBM Plex Mono'; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); text-align:left; padding:8px 10px; border-bottom:2px solid var(--ink)}
.memo-table td{padding:9px 10px; border-bottom:1px solid rgba(203,189,159,.55); font:400 .93rem 'Newsreader'; transition:background .2s}
.memo-table td:first-child{font-weight:600}
.memo-table td:last-child{font:500 10.5px 'IBM Plex Mono'; letter-spacing:.08em; color:var(--pine); white-space:nowrap}
.memo-table tbody tr:hover td{background:rgba(29,92,71,.07)}
/* ---------- terms ---------- */
.terms{border:1px solid var(--ink); background:var(--paper-2); padding:36px 38px; margin:0 0 64px; box-shadow:5px 5px 0 rgba(34,29,21,.1)}
.terms-title{font:900 clamp(1.8rem,3.2vw,2.6rem) 'Fraunces'; margin-bottom:6px}
.terms-title::before{content:"§ "; color:var(--red)}
.terms-sub{font:italic 400 1rem 'Newsreader'; color:var(--muted); margin-bottom:24px}
.terms-grid{display:grid; grid-template-columns:1fr 1fr; gap:26px; font:400 11.5px/2 'IBM Plex Mono'; color:var(--ink-soft)}
.terms-grid p{padding-left:2.2em; text-indent:-2.2em}
.terms-grid p b{color:var(--pine); font-weight:600}
/* ---------- footer ---------- */
.footer{border-top:2px solid var(--ink); position:relative; margin-top:20px}
.footer::after{content:""; position:absolute; left:0; right:0; top:-6px; height:1px; background:var(--ink)}
.foot-inner{max-width:1240px; margin:0 auto; padding:56px 28px 44px}
.foot-total{display:flex; align-items:baseline; gap:20px; flex-wrap:wrap; margin-bottom:36px}
.foot-total .mono{font-size:10px; letter-spacing:.26em; text-transform:uppercase; color:var(--muted)}
.foot-big{font:900 clamp(2.2rem,5vw,4rem) 'Fraunces'; letter-spacing:-.01em}
.foot-big em{font-style:italic; color:var(--pine)}
.foot-sig{display:flex; align-items:flex-end; gap:20px; margin-bottom:32px; flex-wrap:wrap}
.sig{font:700 3rem/1 'Caveat'; transform:rotate(-3deg); border-bottom:1px solid rgba(34,29,21,.4); padding:0 14px 4px}
.sig-cap{font:500 10px 'IBM Plex Mono'; letter-spacing:.18em; text-transform:uppercase; color:var(--muted); padding-bottom:8px}
.colophon{font:italic 400 .95rem/1.75 'Newsreader'; color:var(--muted); max-width:64ch}
.foot-legal{margin-top:20px; font:500 9.5px 'IBM Plex Mono'; letter-spacing:.24em; text-transform:uppercase; color:var(--muted)}
/* ---------- responsive ---------- */
@media (max-width:1020px){
  .invoice{grid-template-columns:1fr; gap:44px; align-items:start; padding:48px 20px}
  .layout{grid-template-columns:1fr; gap:30px; padding:40px 18px}
  .rail{position:static; max-height:none}
  .toc{display:flex; overflow-x:auto; border-bottom:none}
  .toc a{min-width:132px; border-bottom:2px solid var(--line); padding:10px 14px}
  .mast-mid{display:none}
  .e-body{grid-template-columns:1fr}
  .e-side{flex-direction:row; align-items:flex-start}
  .photo{width:150px}
  .e-num{font-size:44px}
  .memo{grid-template-columns:1fr}
  .memo-letter{border-right:none; border-bottom:1px dashed var(--line)}
  .terms-grid{grid-template-columns:1fr}
}
/* ---------- reduced motion ---------- */
@media (prefers-reduced-motion:reduce){
  *{animation:none !important; transition:none !important}
  .grain{animation:none}
  .js .reveal{opacity:1; transform:none}
  .js .verse .lm-i,.js .invoice .lm-i{transform:none}
  .inv-stamp,.e-stamp{opacity:.92}
  .inv-stamp{transform:rotate(8deg)} .e-stamp{transform:rotate(-7deg)}
  .photo img{transform:none}
  .ticker-track{animation:none}
}
</style>
</head>
